"use client";

import { useEffect, useRef, useState, FC, ReactNode } from "react";
import { useDispatch } from "react-redux";
import type { AppDispatch } from "@/redux/store";
import {
  useLazyRefreshTokenQuery,
  useLazyLoadUserQuery,
} from "@/redux/features/api/apiSlice";

interface AuthInitializerProps {
  children: ReactNode;
}

const AuthInitializer: FC<AuthInitializerProps> = ({ children }) => {
  const dispatch = useDispatch<AppDispatch>();
  const didInit = useRef(false);

  const [refreshToken] = useLazyRefreshTokenQuery();
  const [loadUser] = useLazyLoadUserQuery();

  const [isInitialized, setIsInitialized] = useState(false);

  useEffect(() => {
    if (didInit.current) return;
    didInit.current = true;

    const initAuth = async () => {
      try {
        const { data, isError } = await refreshToken();

        if (isError || !data?.status) {
          console.log("ℹ️ No active session - user needs to login");
          return;
        }

        console.log("✅ Session restored successfully");

        const { isError: userError } = await loadUser();
        if (userError) {
          console.error("Failed to load user data");
        }
      } catch (error: any) {
        console.error("❌ Unexpected auth initialization error:", error);
      } finally {
        setIsInitialized(true);
      }
    };

    initAuth();
  }, [refreshToken, loadUser]);

  if (!isInitialized) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return <>{children}</>;
};

export default AuthInitializer;
